const units = [
  {name:'Soldier', icon:'S', attack:4, hp:9, color:'#a3bed5'},
  {name:'Archer', icon:'A', attack:5, hp:5, color:'#a8d8a2'},
  {name:'Skeleton', icon:'Sk', attack:3, hp:7, color:'#d8d5c9'},
  {name:'Slime', icon:'Sl', attack:2, hp:11, color:'#91d5bd'},
  {name:'Swordsman', icon:'Sw', attack:6, hp:6, color:'#d9b3a0'},
  {name:'Orc', icon:'O', attack:5, hp:8, color:'#b6c98a'},
  {name:'Priest', icon:'P', attack:2, hp:6, color:'#e2cc9a'},
  {name:'Bat', icon:'B', attack:4, hp:4, color:'#bda8dd'}
];
const $ = id => document.getElementById(id);
let state;
function fresh(){state={round:1,wins:0,gold:12,player:Array(6).fill(null),enemy:Array(6).fill(null),offers:[],phase:'shop',playerHp:30,enemyHp:30,log:['Recruit units and start a battle to see the action.']};rollOffers();render()}
function sample(pool,count){const copy=[...pool],out=[];while(copy.length&&out.length<count)out.push(copy.splice(Math.floor(Math.random()*copy.length),1)[0]);return out}
function rollOffers(){state.offers=sample(units,6)}
function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),2300)}
function unitMarkup(unit){return `<span class="unit-icon" style="--unit-color:${unit.color}">${unit.icon}</span><span class="unit-name">${unit.name}</span><span class="unit-stat">⚔ ${unit.attack} · ♥ ${unit.hp}</span>`}
function renderBoard(id,board,editable){$(id).innerHTML=board.map((unit,index)=>`<div class="slot ${unit?'filled':''}" data-slot="${index}"><span class="number">0${index+1}</span>${unit?unitMarkup(unit):'<span>EMPTY</span>'}${unit&&editable?`<button aria-label="Remove ${unit.name} from slot ${index+1}" data-remove="${index}">×</button>`:''}</div>`).join('')}
function render(){const s=state;$('round-label').textContent=`ROUND ${s.round}`;$('wins-label').textContent=`${s.wins} ${s.wins===1?'WIN':'WINS'}`;$('gold-label').textContent=`◆ ${s.gold} GOLD`;$('player-health').textContent=`${s.playerHp} / 30 HP`;$('enemy-health').textContent=`${s.enemyHp} / 30 HP`;$('log-round').textContent=`ROUND ${s.round}`;$('phase-label').textContent=s.phase==='shop'?'PREPARE YOUR LINEUP':'BATTLE COMPLETE';$('heading').textContent=s.phase==='shop'?'Build your tableau':s.enemyHp<=0?'Victory!':'Battle finished';$('hint').textContent=s.phase==='shop'?'Recruit units, then place them in the six battle slots. Position matters: the front slot attacks first.':'Review the match feed, then advance to the next round.';$('battle-button').innerHTML=s.phase==='shop'?'Start battle <span>→</span>':'Next round <span>→</span>';$('battle-button').disabled=s.phase==='shop'&&!s.player.some(Boolean);$('reroll-button').disabled=s.phase!=='shop'||s.gold<1;renderBoard('player-board',s.player,s.phase==='shop');renderBoard('enemy-board',s.enemy,false);$('offers').innerHTML=s.offers.map((u,i)=>`<div class="offer"><span class="unit-icon" style="--unit-color:${u.color}">${u.icon}</span><span class="offer-info"><span class="offer-name">${u.name}</span><span class="offer-detail">⚔ ${u.attack} · ♥ ${u.hp}</span></span><button class="buy" data-buy="${i}" ${s.phase!=='shop'||s.gold<3||!s.player.includes(null)?'disabled':''}>◆ 3</button></div>`).join('');$('battle-log').innerHTML=s.log.map(x=>`<li>${x}</li>`).join('')}
function buy(index){if(state.phase!=='shop'||state.gold<3)return toast('Not enough gold');const slot=state.player.indexOf(null);if(slot<0)return toast('All six slots are full');state.player[slot]=state.offers[index];state.offers.splice(index,1);state.gold-=3;state.log=[`${state.player[slot].name} recruited into slot ${slot+1}.`];render()}
function battle(){const s=state;if(s.phase==='done'){s.round++;s.gold=12;s.playerHp=30;s.enemyHp=30;s.enemy=Array(6).fill(null);s.phase='shop';s.log=['A new round begins. Adjust your lineup and recruit reinforcements.'];rollOffers();render();return}if(!s.player.some(Boolean))return;const roster=sample(units,6);s.enemy=roster;s.playerHp=30;s.enemyHp=30;s.log=[];let playerPool=s.player.filter(Boolean).map(u=>({...u,currentHp:u.hp}));let enemyPool=roster.map(u=>({...u,currentHp:u.hp}));let step=0;while(playerPool.length&&enemyPool.length&&s.playerHp>0&&s.enemyHp>0&&step<40){const attacker=playerPool[0],defender=enemyPool[0];defender.currentHp-=attacker.attack;s.log.push(`${attacker.name} hits ${defender.name} for ${attacker.attack}.`);if(defender.currentHp<=0){s.log.push(`Opponent ${defender.name} falls.`);enemyPool.shift()}if(enemyPool.length){const foe=enemyPool[0],target=playerPool[0];target.currentHp-=foe.attack;s.log.push(`Opponent ${foe.name} hits ${target.name} for ${foe.attack}.`);if(target.currentHp<=0){s.log.push(`Your ${target.name} falls.`);playerPool.shift()}}step++}s.enemyHp=Math.max(0,30-enemyPool.reduce((sum,u)=>sum+u.currentHp,0));s.playerHp=Math.max(0,30-playerPool.reduce((sum,u)=>sum+u.currentHp,0));if(playerPool.length&&!enemyPool.length){s.enemyHp=0;s.wins++;s.log.push('Victory — your tableau holds the field.')}else if(enemyPool.length&&!playerPool.length){s.playerHp=0;s.log.push('Defeat — regroup for the next round.')}else{s.log.push('The battle ends in a draw.')}s.phase='done';render()}
document.addEventListener('click',event=>{const buyButton=event.target.closest('[data-buy]');if(buyButton){buy(Number(buyButton.dataset.buy));return}const removeButton=event.target.closest('[data-remove]');if(removeButton){state.player[Number(removeButton.dataset.remove)]=null;state.gold+=3;state.log=['Unit sold for 3 gold.'];render()}});$('battle-button').addEventListener('click',battle);$('reroll-button').addEventListener('click',()=>{if(state.gold<1)return toast('Not enough gold');state.gold--;rollOffers();render()});$('reset-button').addEventListener('click',fresh);fresh();
